/// Probe every common outbound SMTP port with a 3-second timeout
/// each. Runs all probes in parallel via `tokio::join!`. Returns a
/// Vec preserving the well-known port order (25, 465, 587, 2525)
/// so the UI renders a stable table.
///
/// Targets:
///   * 25  — gmail-smtp-in.l.google.com (real MX, port 25 receiving)
///   * 465 — smtp.gmail.com (implicit-TLS submission)
///   * 587 — smtp.gmail.com (STARTTLS submission)
///   * 2525 — smtp.mailgun.org (alt-submission accepted by many
///            providers when 587 is blocked; some operators use
///            it as a last-resort port)
///
/// Each probe is a TCP-connect, no SMTP banner read — we just
/// want to know whether the egress firewall allows the port.
async fn probe_outbound_smtp_all() -> Vec<hyperion_types::MtaPortProbe> {
    let p25 = single_smtp_probe(
        25,
        "gmail-smtp-in.l.google.com",
        "MX delivery (recipient servers)",
    );
    let p465 = single_smtp_probe(465, "smtp.gmail.com", "Implicit-TLS submission");
    let p587 = single_smtp_probe(587, "smtp.gmail.com", "STARTTLS submission (most common)");
    let p2525 = single_smtp_probe(
        2525,
        "smtp.mailgun.org",
        "Alt-submission (when 587 blocked)",
    );
    let (r25, r465, r587, r2525) = tokio::join!(p25, p465, p587, p2525);
    vec![r25, r465, r587, r2525]
}

async fn single_smtp_probe(port: u16, host: &str, purpose: &str) -> hyperion_types::MtaPortProbe {
    use std::time::Instant;
    use tokio::net::TcpStream;
    const TIMEOUT: std::time::Duration = std::time::Duration::from_secs(3);
    let target = format!("{host}:{port}");
    let started = Instant::now();
    let connect = tokio::time::timeout(TIMEOUT, TcpStream::connect(&target)).await;
    let elapsed = started.elapsed().as_millis() as u64;
    match connect {
        Ok(Ok(_)) => hyperion_types::MtaPortProbe {
            port,
            host: host.to_string(),
            reachable: true,
            latency_ms: elapsed,
            error: String::new(),
            purpose: purpose.to_string(),
        },
        Ok(Err(e)) => hyperion_types::MtaPortProbe {
            port,
            host: host.to_string(),
            reachable: false,
            latency_ms: 0,
            error: format!("{e}"),
            purpose: purpose.to_string(),
        },
        Err(_) => hyperion_types::MtaPortProbe {
            port,
            host: host.to_string(),
            reachable: false,
            latency_ms: 0,
            error: "timeout after 3 s".to_string(),
            purpose: purpose.to_string(),
        },
    }
}

/// Detect a WordPress install at `<root_dir>` by checking for the
/// two files that any WP install (Hyperion-managed, SSH-installed,
/// migrated, restored from backup) MUST have: `wp-config.php` and
/// `wp-includes/version.php`. Returns the version string parsed
/// out of version.php's `$wp_version = '<x.y.z>'` line, or
/// `"unknown"` when both files are present but the version line
/// can't be parsed (corrupt install, custom fork, etc.).
///
/// Returns `None` when either file is missing or unreadable —
/// strict "no WP here" answer. Never panics. Never errors out
/// (the caller treats `None` as "no install" the same way it
/// treats an empty DB row).
/// Open a path for metadata changes without following a final symlink.
/// Directories are allowed here — `site_dirs` tightens logs/ and tmp/.
fn rustix_open_no_follow(path: &str) -> Result<std::fs::File, String> {
    hyperion_adapters::fs::open_path_no_follow(std::path::Path::new(path))
        .map_err(|e| e.to_string())
}

/// chmod a single path, reporting failure rather than swallowing it.
async fn chmod_path(path: &str, mode: u32) -> Result<(), String> {
    if path.is_empty() || path.contains(['\n', '\r', '\0']) {
        return Err("illegal path".into());
    }
    // O_NOFOLLOW on the way in, then fchmod the descriptor. `set_permissions`
    // takes a PATH and follows links, and every path this is called with sits
    // inside a directory the SITE USER owns — so pointing wp-config.php at
    // /etc/passwd and pressing "Tighten wp-config.php" on your own site would
    // chmod that instead.
    use std::os::unix::fs::MetadataExt;
    use std::os::unix::fs::PermissionsExt;
    let file = match rustix_open_no_follow(path) {
        Ok(f) => f,
        Err(e) => return Err(e),
    };
    let md = file.metadata().map_err(|e| format!("stat {path}: {e}"))?;
    let ft = md.file_type();
    if ft.is_file() {
        // A second link to a regular file is the attack: the site user
        // hardlinks a root-owned file into their own tree and has this chmod
        // it for them. One link means the name we opened is the only one.
        if md.nlink() != 1 {
            return Err(format!(
                "{path} has {} hard links — refusing to chmod it",
                md.nlink()
            ));
        }
    } else if !ft.is_dir() {
        // O_NOFOLLOW already excludes symlinks; this excludes devices,
        // sockets and fifos, which have no business being chmod'ed here.
        return Err(format!(
            "{path} is neither a regular file nor a directory — refusing to chmod it"
        ));
    }
    // NOTE for directories: the link count is NOT checked, and must not be.
    // Every directory has at least two links — its own name in the parent and
    // the `.` entry inside it — plus one more per subdirectory. Applying the
    // file rule here refused EVERY directory, always, with "logs has 2 hard
    // links", which is how a permission repair reported a perfectly ordinary
    // tree as an attack. Nothing is given up by skipping it: Linux does not
    // allow hard links to directories at all.
    file.set_permissions(std::fs::Permissions::from_mode(mode))
        .map_err(|e| format!("chmod {mode:o} {path}: {e}"))
}

#[cfg(test)]
mod chmod_path_tests {
    use super::chmod_path;
    use std::os::unix::fs::PermissionsExt;

    /// A directory has two links before it contains anything — its name in
    /// the parent, and its own `.` — and one more per subdirectory. The
    /// hard-link guard is a rule about regular FILES, and applying it here
    /// refused every directory a permission repair touched, reporting an
    /// ordinary site tree as an attack: "logs has 2 hard links".
    #[tokio::test]
    async fn a_directory_is_chmod_able_despite_its_link_count() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let dir = tmp.path().join("logs");
        std::fs::create_dir(&dir).expect("create logs");
        // Give it a subdirectory so the count is 3, not merely 2.
        std::fs::create_dir(dir.join("sub")).expect("create sub");
        let path = dir.to_string_lossy().into_owned();

        chmod_path(&path, 0o750).await.expect("directory refused");
        let mode = std::fs::metadata(&dir).expect("stat").permissions().mode();
        assert_eq!(mode & 0o777, 0o750);
    }

    /// The guard itself must survive: a second link to a regular file is how
    /// a tenant gets a root-owned file chmod'ed on their behalf.
    #[tokio::test]
    async fn a_hardlinked_file_is_still_refused() {
        let tmp = tempfile::tempdir().expect("tempdir");
        let real = tmp.path().join("wp-config.php");
        std::fs::write(&real, b"<?php\n").expect("write");
        let link = tmp.path().join("hardlink.php");
        std::fs::hard_link(&real, &link).expect("hard_link");

        let err = chmod_path(&link.to_string_lossy(), 0o600)
            .await
            .expect_err("a hardlinked file must be refused");
        assert!(err.contains("hard links"), "{err}");

        // And a plain file with one link still goes through.
        let plain = tmp.path().join("alone.php");
        std::fs::write(&plain, b"<?php\n").expect("write");
        chmod_path(&plain.to_string_lossy(), 0o640)
            .await
            .expect("a single-link file should be allowed");
    }
}

/// Split the administrator notification address setting into addresses.
///
/// One field, any number of people. Operators write such a list every way
/// there is — commas, semicolons, newlines out of a pasted column — so all of
/// them are accepted rather than making the operator guess which separator
/// this particular field wanted.
///
/// Anything without an `@` is dropped instead of being sent to: the field is
/// free text, and a stray word between two commas would otherwise fail every
/// send that shares its batch. Duplicates are dropped too, so the same person
/// listed twice is not mailed twice.
fn parse_recipient_list(raw: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for part in raw.split([',', ';', '\n', '\r', ' ', '\t']) {
        let a = part.trim().trim_matches(['<', '>']).trim();
        // Cheapest possible check that it is an address at all: something
        // before an @ and something after it. Full validation belongs to the
        // SMTP server, which will reject what it does not like.
        if a.is_empty() || !a.contains('@') || a.starts_with('@') || a.ends_with('@') {
            continue;
        }
        if !out.iter().any(|e| e.eq_ignore_ascii_case(a)) {
            out.push(a.to_string());
        }
    }
    out
}

#[cfg(test)]
mod recipient_list_tests {
    use super::parse_recipient_list;

    #[test]
    fn one_address_still_works() {
        assert_eq!(parse_recipient_list("ops@example.cz"), ["ops@example.cz"]);
        assert_eq!(
            parse_recipient_list("  ops@example.cz  "),
            ["ops@example.cz"]
        );
    }

    /// Every separator an operator might reach for, including a column
    /// pasted out of a spreadsheet.
    #[test]
    fn a_list_is_split_however_it_was_written() {
        let want = ["a@x.cz", "b@x.cz", "c@x.cz"];
        for raw in [
            "a@x.cz,b@x.cz,c@x.cz",
            "a@x.cz, b@x.cz, c@x.cz",
            "a@x.cz; b@x.cz; c@x.cz",
            "a@x.cz\nb@x.cz\nc@x.cz",
            "a@x.cz b@x.cz c@x.cz",
            "<a@x.cz>, <b@x.cz>, <c@x.cz>",
        ] {
            assert_eq!(parse_recipient_list(raw), want, "{raw:?}");
        }
    }

    /// A stray word must not become a recipient — one unsendable address
    /// would otherwise fail alongside the real ones.
    #[test]
    fn non_addresses_are_dropped_not_sent_to() {
        assert_eq!(
            parse_recipient_list("ops@example.cz, and, also, admin@example.cz"),
            ["ops@example.cz", "admin@example.cz"]
        );
        for raw in ["", "   ", ",,,", "nobody", "@x.cz", "a@"] {
            assert!(parse_recipient_list(raw).is_empty(), "{raw:?}");
        }
    }

    #[test]
    fn the_same_person_is_not_mailed_twice() {
        assert_eq!(
            parse_recipient_list("ops@example.cz, OPS@Example.cz, ops@example.cz"),
            ["ops@example.cz"]
        );
    }
}

/// The numeric uid of `user`, or `None` when there is no such account.
///
/// Compared numerically rather than by name: `find -printf %U` reports uids,
/// and resolving those back to names for every entry would be a lookup per
/// file on a tree with thousands of them.
async fn uid_of_user(user: &str) -> Option<u32> {
    if user.is_empty() || user.contains([':', '\n', '\r', '\0']) {
        return None;
    }
    let out = hyperion_adapters::cmd::run("/usr/bin/getent", &["passwd", user])
        .await
        .ok()?;
    out.split(':').nth(2)?.trim().parse().ok()
}

pub(crate) async fn detect_wp_install_on_disk(root_dir: &str) -> Option<String> {
    use std::path::Path;
    let root = Path::new(root_dir);
    // wp-config.php — proof that WP setup has run at all.
    let wp_config = root.join("wp-config.php");
    if tokio::fs::metadata(&wp_config).await.is_err() {
        return None;
    }
    // wp-includes/version.php — has the version string.
    let version_php = root.join("wp-includes").join("version.php");
    let Ok(body) = tokio::fs::read_to_string(&version_php).await else {
        // wp-config exists but core is missing — this is a partial
        // install. Treat as "no WP" rather than fake a version,
        // so the operator's install button stays available to
        // recover it.
        return None;
    };
    // Parse `$wp_version = '<x.y.z>'` (single or double quotes,
    // any amount of whitespace around the `=`). Defensive: only
    // accept versions of the shape [digit.][...] so we never
    // surface garbage from a corrupt file.
    for raw in body.lines() {
        let line = raw.trim_start();
        // Skip comments — both `//` and `#` and `/*` styles can
        // legally appear above the version line.
        if line.starts_with("//") || line.starts_with('#') || line.starts_with("/*") {
            continue;
        }
        let Some(rest) = line.strip_prefix("$wp_version") else {
            continue;
        };
        // Allow optional whitespace, then `=`, then any whitespace,
        // then a quote.
        let after_eq = match rest.split_once('=') {
            Some((_, r)) => r.trim_start(),
            None => continue,
        };
        let quote_char = after_eq.chars().next();
        let inside = match quote_char {
            Some(q @ ('\'' | '"')) => {
                let s = &after_eq[1..];
                match s.find(q) {
                    Some(end) => &s[..end],
                    None => continue,
                }
            }
            _ => continue,
        };
        if inside.is_empty() {
            continue;
        }
        if !inside
            .chars()
            .all(|c| c.is_ascii_digit() || c == '.' || c == '-' || c.is_ascii_alphanumeric())
        {
            continue;
        }
        return Some(inside.to_string());
    }
    // version.php existed but didn't match the expected shape —
    // still WP, just unknown version. The detail UI shows "unknown"
    // as the version which is honest about what we observed.
    Some("unknown".to_string())
}

fn clamp_limits(mut l: hyperion_types::HostingLimits) -> hyperion_types::HostingLimits {
    // Hard sanity ranges. Refusing to store nonsense is more useful than
    // silently mis-applying it later.
    l.php_memory_mb = l.php_memory_mb.clamp(16, 8192);
    l.php_max_exec_secs = l.php_max_exec_secs.clamp(1, 3600);
    l.php_max_children = l.php_max_children.clamp(1, 200);
    l.php_max_requests = l.php_max_requests.clamp(0, 1_000_000);
    l.db_max_connections = l.db_max_connections.clamp(1, 1000);
    if let Some(b) = l.disk_soft_bytes {
        l.disk_soft_bytes = Some(b.max(0));
    }
    if let Some(b) = l.disk_hard_bytes {
        l.disk_hard_bytes = Some(b.max(0));
    }
    if let Some(b) = l.bw_monthly_bytes {
        l.bw_monthly_bytes = Some(b.max(0));
    }
    if let Some(k) = l.throttle_kbps {
        l.throttle_kbps = Some(k.clamp(1, 10_000_000));
    }
    l
}

fn limits_to_row(
    id: &HostingId,
    l: &hyperion_types::HostingLimits,
    now: i64,
) -> hyperion_state::limits::LimitsRow {
    hyperion_state::limits::LimitsRow {
        hosting_id: id.clone(),
        disk_soft_bytes: l.disk_soft_bytes,
        disk_hard_bytes: l.disk_hard_bytes,
        inode_soft: l.inode_soft,
        inode_hard: l.inode_hard,
        php_memory_mb: l.php_memory_mb,
        php_max_exec_secs: l.php_max_exec_secs,
        php_max_children: l.php_max_children,
        php_max_requests: l.php_max_requests,
        db_max_connections: l.db_max_connections,
        bw_monthly_bytes: l.bw_monthly_bytes,
        over_bw_policy: l.over_bw_policy.as_str().to_string(),
        throttle_kbps: l.throttle_kbps,
        updated_at: now,
    }
}

fn row_to_limits(row: hyperion_state::limits::LimitsRow) -> hyperion_types::HostingLimits {
    let policy = match row.over_bw_policy.as_str() {
        "throttle" => hyperion_types::OverBwPolicy::Throttle,
        _ => hyperion_types::OverBwPolicy::Suspend,
    };
    hyperion_types::HostingLimits {
        disk_soft_bytes: row.disk_soft_bytes,
        disk_hard_bytes: row.disk_hard_bytes,
        inode_soft: row.inode_soft,
        inode_hard: row.inode_hard,
        php_memory_mb: row.php_memory_mb,
        php_max_exec_secs: row.php_max_exec_secs,
        php_max_children: row.php_max_children,
        php_max_requests: row.php_max_requests,
        db_max_connections: row.db_max_connections,
        bw_monthly_bytes: row.bw_monthly_bytes,
        over_bw_policy: policy,
        throttle_kbps: row.throttle_kbps,
    }
}

// ===== Internal-error helper =====
trait InternalWith {
    fn internal_with(msg: String) -> Self;
}
impl InternalWith for RpcError {
    fn internal_with(msg: String) -> Self {
        tracing::error!(error=%msg, "internal error");
        // Carry the message on the wire too — the operator-facing
        // 502 page renders it. It used to be log-only, which made
        // every internal failure show as a context-free "internal
        // error" (e.g. the trash CHECK-constraint bug took a day
        // of guessing instead of one glance).
        RpcError::Internal { message: msg }
    }
}

// Allow `RpcError::Internal_with(..)` call style.
#[allow(non_snake_case)]
impl RpcErrorExt for RpcError {
    fn Internal_with(msg: String) -> Self {
        <RpcError as InternalWith>::internal_with(msg)
    }
}

trait RpcErrorExt {
    #[allow(non_snake_case)]
    fn Internal_with(msg: String) -> Self;
}

/// Push a per-user disk cap into the kernel for the filesystem carrying
/// `home_dir`, via `setquota -u <user> <soft> <hard> 0 0 <mount>`.
///
/// Semantics by request:
///   - **positive cap** (soft>0 || hard>0): the cap must be enforceable, so if
///     kernel quotas aren't active on that mount yet we enable them
///     automatically (fstab + remount + quotacheck + quotaon) and retry. If
///     that can't finish live we return a clear, reboot-aware message — the
///     caller still saves the policy, so it applies after the reboot.
///   - **no cap** (soft==0 && hard==0): clear any existing cap when quotas are
///     active; a no-op (Ok) when they're not — we don't touch fstab/remount
///     just to express "no limit", so a memory/bandwidth-only save never
///     triggers a disk-quota error.
///
/// Inode limits are left at 0 (no cap) — operators care about disk space, not
/// file count.
///
/// The active-state probe uses the SAME canonical parser as the enable/read
/// path (`ext_quota_on` → `quota_report_shows_on`, matching `quotaon -p`'s
/// `… is on`). A previous bespoke scan here looked for the literal
/// `user quotas on`, which modern quota-tools never print (`user quota on … is
/// on`), so it false-negatived and refused setquota even when quotas were on.
/// Outcome of a successful `apply_disk_quota`. Distinguishes a real `setquota`
/// push from a no-op so the caller doesn't stamp `applied_at` (i.e. claim "last
/// applied to kernel") when nothing actually ran.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum QuotaApply {
    /// `setquota` ran — the cap (or its removal) is live in the kernel.
    Applied,
    /// No disk cap requested and quotas aren't active — nothing to do.
    NoOp,
}

/// Prefix that marks a "saved, pending a node reboot" error so the web boundary
/// can render it as an amber "activates after reboot" notice rather than a red
/// "kernel rejected it" failure. The boot reconciler (`quotas_reapply_on_boot`)
/// re-pushes the cap once the reboot brings the subsystem up.
const QUOTA_PENDING_REBOOT_PREFIX: &str = "kernel quotas need a reboot to finish activating";

async fn apply_disk_quota(
    user: &str,
    home_dir: &str,
    soft_kib: i64,
    hard_kib: i64,
) -> Result<QuotaApply, String> {
    let mount = mount_point_for(home_dir).await;
    let on = match &mount {
        Some(mp) => ext_quota_on(mp).await,
        None => false,
    };

    let wants_cap = soft_kib > 0 || hard_kib > 0;
    if !wants_cap && !on {
        // Nothing to enforce and nothing enabled to clear — success no-op.
        // (No setquota ran, so the caller must NOT stamp applied_at.)
        return Ok(QuotaApply::NoOp);
    }

    // The filesystem to target with setquota. Resolved from the home dir, or
    // from enable_kernel_quotas when we had to bring quotas up. We NEVER fall
    // back to `setquota -a` (every quota-enabled fs) — that would broadcast a
    // per-user cap onto unrelated mounts.
    let mut target_mount = mount.clone();

    if wants_cap && !on {
        // Bring kernel quotas up so the cap is actually enforceable.
        // enable_kernel_quotas is idempotent: the fstab splice no-ops when the
        // option is already present and an already-active fs short-circuits. On
        // success we fall through to setquota; otherwise surface why it didn't.
        let summary = enable_kernel_quotas(home_dir).await;
        if !summary.ok {
            return Err(if summary.requires_reboot {
                format!(
                    "{QUOTA_PENDING_REBOOT_PREFIX} — {} The limit is saved and will be enforced after the node reboots.",
                    summary.message
                )
            } else {
                format!(
                    "couldn't enable kernel quotas automatically: {}",
                    summary.message
                )
            });
        }
        if target_mount.as_deref().unwrap_or("").is_empty() && !summary.mount_point.is_empty() {
            target_mount = Some(summary.mount_point);
        }
    }

    let mount_arg = match target_mount {
        Some(mp) if !mp.is_empty() => mp,
        _ => return Err("couldn't determine which filesystem to apply the disk quota to".into()),
    };
    let out = tokio::process::Command::new("/usr/sbin/setquota")
        .args([
            "-u",
            user,
            &soft_kib.to_string(),
            &hard_kib.to_string(),
            "0",
            "0",
            &mount_arg,
        ])
        .output()
        .await
        .map_err(|e| format!("spawn setquota: {e}"))?;
    if out.status.success() {
        Ok(QuotaApply::Applied)
    } else {
        let stderr = String::from_utf8_lossy(&out.stderr);
        let stdout = String::from_utf8_lossy(&out.stdout);
        Err(format!(
            "setquota exit {}: {}{}",
            out.status.code().unwrap_or(-1),
            stderr.trim(),
            stdout.trim(),
        ))
    }
}

/// Probe current disk usage for the hosting:
///   1. `quota -u <user>` if quotas are enabled — single line, fast,
///      reports the kernel's view (matches what `setquota` enforces)
///   2. fallback `du -sk <home>` if quota is unavailable — slower but
///      always works (lets the UI show *some* number even on VPSes
///      without quotas configured).
///
/// Longest mountpoint in /proc/self/mounts that contains `path` (so we can ask
/// `quotaon -p` about the right filesystem). Mirrors the discovery in
/// `enable_kernel_quotas`.
async fn mount_point_for(path: &str) -> Option<String> {
    let mounts = tokio::fs::read_to_string("/proc/self/mounts").await.ok()?;
    let mut best: Option<String> = None;
    for line in mounts.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        if f.len() < 2 {
            continue;
        }
        let mp = unescape_mount_field(f[1]);
        let covers =
            path == mp || mp == "/" || path.starts_with(&format!("{}/", mp.trim_end_matches('/')));
        if covers && best.as_ref().map(|m| mp.len() > m.len()).unwrap_or(true) {
            best = Some(mp);
        }
    }
    best
}

/// `hosting_kv` key: per-hosting overage policy ("notify" | "suspend").
const QUOTA_KV_ACTION: &str = "quota_exceed_action";
/// `hosting_kv` key: de-dup state for the enforce loop ("ok"|"over"|"suspended").
const QUOTA_KV_STATE: &str = "quota_exceed_state";
/// `hosting_kv` key: per-hosting recurring-backup cadence
/// ("off"|"daily"|"weekly"|"monthly"); seeded from the profile at apply.
const BACKUP_KV_CADENCE: &str = "backup_cadence";
/// `hosting_kv` key: unix-secs of the last successful scheduled backup.
const BACKUP_KV_LAST_RUN: &str = "backup_last_run_at";
/// `hosting_kv` key: the ONE off-site target this hosting's backups go to,
/// held as `backup_targets.name` (unique in that table). Absent/blank = the
/// node default, i.e. every target the caller resolved — what every install
/// did before this key existed. The name rather than the row id because a
/// worker has no `backup_targets` table of its own: the name is the only
/// identifier that survives into the `S3BackupTarget` the master sends with
/// the request, so it's the only one both sides can agree on.
const BACKUP_KV_TARGET: &str = "backup_target";

/// Where a backup run's off-site targets came from, and therefore what an
/// EMPTY set of them means. Nothing downstream can tell from the list alone,
/// and guessing is wrong in both directions: read every empty list as
/// "nothing was wanted" and a worker's scheduled backups quietly stop leaving
/// the node; read every empty list as a failure and an install that never
/// bought off-site storage collects a red audit row per backup.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OffsiteSource {
    /// The panel or the API resolved the cluster's targets on the MASTER
    /// (where the table lives) and sent them with the request. Empty
    /// therefore means the operator has none that can take a copy — which
    /// the Backups card already says — so there is nothing to report.
    Caller,
    /// A scheduled run, using THIS node's own `backup_targets` table. On the
    /// master that is the same table the panel reads; on a worker it is empty
    /// by design, so empty here means the cluster's targets never reached the
    /// run rather than that no copy was wanted.
    ThisNode,
    /// An internal snapshot taken as a rollback safety net — the pre-export
    /// and pre-push backups. Nothing off-site was ever intended, so nothing
    /// is missing when nothing is uploaded.
    NotWanted,
}

/// Why a scheduled backup on a worker never leaves the node. Shared by the
/// audit row and the sweep's log line so the operator reads one explanation,
/// not two that have drifted apart.
const OFFSITE_WORKER_HAS_NO_TARGETS: &str =
    "no off-site target reached this scheduled run: the cluster's off-site targets live in the \
     master's table and a worker keeps none of its own, so this backup exists only on this node. \
     Until that is fixed, run the backup from the panel (which sends the targets with the \
     request) or give this node its own copy via [remote_backup] in its agent.toml";

/// Which of the resolved off-site targets one hosting's backup may use.
/// Borrows the caller's slice — nothing is copied until an upload happens.
#[derive(Debug, PartialEq, Eq)]
enum OffsiteChoice<'a> {
    /// No pin: every target the caller resolved. Never empty — "resolved
    /// nothing" is `NoTargets`, which is a different thing to report.
    NodeDefault(&'a [hyperion_types::S3BackupTarget]),
    /// Pinned to one target that is in the resolved set.
    Pinned(&'a hyperion_types::S3BackupTarget),
    /// Pinned to a target that ISN'T in the resolved set — disabled, deleted,
    /// renamed, its secret file didn't read, or this run carries no targets
    /// at all. Nothing is pushed: someone chose where this client's data
    /// goes, so silently falling back to the node's other buckets would put
    /// it somewhere nobody picked.
    Unresolved(&'a str),
    /// Unpinned, and the run resolved no targets. Whether that is a failure
    /// depends on where the (empty) list came from — see `OffsiteSource`.
    NoTargets,
}

/// Resolve one hosting's off-site destination against the targets the caller
/// already resolved (the master's table for a manual run, this node's for a
/// scheduled one).
///
/// An empty `resolved` used to swallow the pin and report the node default,
/// on the grounds that the callers passing none wanted none. That is what let
/// a worker's scheduled backup ignore a pin in silence: the caller's intent
/// now travels with the run as an `OffsiteSource`, so this function can say
/// plainly that a pinned target was not available.
fn choose_offsite_targets<'a>(
    pin: Option<&'a str>,
    resolved: &'a [hyperion_types::S3BackupTarget],
) -> OffsiteChoice<'a> {
    match pin.map(str::trim).filter(|s| !s.is_empty()) {
        None if resolved.is_empty() => OffsiteChoice::NoTargets,
        None => OffsiteChoice::NodeDefault(resolved),
        Some(name) => match resolved.iter().find(|t| t.name == name) {
            Some(t) => OffsiteChoice::Pinned(t),
            None => OffsiteChoice::Unresolved(name),
        },
    }
}

/// Canonicalise a backup cadence string to one of the four known values; any
/// unknown/empty input becomes "off" so a stray value never schedules backups.
fn canonical_backup_cadence(c: &str) -> &'static str {
    match c.trim() {
        "daily" => "daily",
        "weekly" => "weekly",
        "monthly" => "monthly",
        _ => "off",
    }
}

/// Seconds in one backup cadence, or `None` for "off"/unknown (never due).
fn backup_cadence_secs(c: &str) -> Option<i64> {
    match canonical_backup_cadence(c) {
        "daily" => Some(86_400),
        "weekly" => Some(7 * 86_400),
        "monthly" => Some(30 * 86_400),
        _ => None,
    }
}

/// A scheduled backup is due when the cadence has elapsed since the last run.
/// `last_run == 0` (never) is always due, so enabling a cadence triggers a
/// prompt first backup.
fn backup_due(cadence_secs: i64, last_run: i64, now: i64) -> bool {
    now.saturating_sub(last_run) >= cadence_secs
}

/// Per-hosting policy for when disk usage crosses the hard cap. Stored in
/// `hosting_kv` under `quota_exceed_action`; seeded from the profile at create.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub(crate) enum QuotaExceedAction {
    /// Send a notification only (default). Where kernel quotas are enabled,
    /// setquota also blocks writes at the cap; where they're off, this alert is
    /// the only signal.
    Notify,
    /// Suspend the site (and notify).
    Suspend,
}
impl QuotaExceedAction {
    pub(crate) fn parse(s: &str) -> Self {
        match s.trim() {
            "suspend" => Self::Suspend,
            _ => Self::Notify,
        }
    }
    pub(crate) fn as_str(self) -> &'static str {
        match self {
            Self::Suspend => "suspend",
            Self::Notify => "notify",
        }
    }
}

/// De-dup state for the enforce loop, stored per hosting in `hosting_kv` under
/// `quota_exceed_state`. `Suspended` means WE auto-suspended it (so we may
/// auto-resume); `Released` means we suspended it but an operator manually
/// resumed it — we hold off and NEVER auto-re-suspend until usage drops back
/// well under the cap. A manually/expiry-suspended site never reaches these.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum QuotaState {
    Ok,
    Over,
    Suspended,
    Released,
}
impl QuotaState {
    fn parse(s: &str) -> Self {
        match s.trim() {
            "over" => Self::Over,
            "suspended" => Self::Suspended,
            "released" => Self::Released,
            _ => Self::Ok,
        }
    }
    fn as_str(self) -> &'static str {
        match self {
            Self::Over => "over",
            Self::Suspended => "suspended",
            Self::Released => "released",
            Self::Ok => "ok",
        }
    }
}

/// What `quota_enforce_tick` should do for one hosting this round.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum QuotaStep {
    Nothing,
    NotifyOver,
    Suspend,
    AutoResume,
}

/// Precedence for a `SuspendReason::label()`. Operator/lifecycle holds (manual,
/// expired) outrank automated usage holds (over-disk, over-bandwidth). A second
/// `suspend()` on an already-suspended site only overwrites the recorded reason
/// when the incoming one strictly outranks the current — so a manual/expiry
/// hold "sticks" over an auto over-disk suspend (and the quota loop then leaves
/// it alone), while a lower-or-equal reason stays idempotent.
fn suspend_reason_rank(label: &str) -> u8 {
    match label {
        "manual" | "expired" => 2,
        _ => 1, // over-disk, over-bandwidth, or unknown/missing
    }
}

/// Pure decision core: given current disk usage vs the hard cap, the configured
/// action, and the last recorded state, return (step, new_state). Auto-resume
/// uses **90%-of-cap hysteresis** so a site hovering at the limit can't flap
/// suspend/resume. The caller separately guards the hosting's real
/// Active/Suspended state + the authoritative suspension reason so a manually-
/// or expiry-suspended site is never auto-resumed.
fn quota_enforce_decide(
    used_kib: i64,
    hard_cap_kib: i64,
    action: QuotaExceedAction,
    state: QuotaState,
) -> (QuotaStep, QuotaState) {
    if hard_cap_kib <= 0 {
        return (QuotaStep::Nothing, QuotaState::Ok);
    }
    let over = used_kib >= hard_cap_kib;
    // 90% hysteresis, but never round the floor below 1 KiB — otherwise a
    // 1-KiB cap could never report "well under" and would never re-arm.
    let well_under = used_kib < (hard_cap_kib * 9 / 10).max(1);

    match state {
        QuotaState::Suspended => {
            if well_under {
                (QuotaStep::AutoResume, QuotaState::Ok)
            } else {
                (QuotaStep::Nothing, QuotaState::Suspended)
            }
        }
        // We suspended it; an operator manually resumed it. Respect that: never
        // auto-re-suspend. Only re-arm (back to Ok) once usage drops well under.
        QuotaState::Released => {
            if well_under {
                (QuotaStep::Nothing, QuotaState::Ok)
            } else {
                (QuotaStep::Nothing, QuotaState::Released)
            }
        }
        QuotaState::Ok | QuotaState::Over => {
            if over {
                match action {
                    QuotaExceedAction::Suspend => (QuotaStep::Suspend, QuotaState::Suspended),
                    QuotaExceedAction::Notify if state == QuotaState::Over => {
                        (QuotaStep::Nothing, QuotaState::Over) // already notified
                    }
                    QuotaExceedAction::Notify => (QuotaStep::NotifyOver, QuotaState::Over),
                }
            } else if well_under {
                (QuotaStep::Nothing, QuotaState::Ok) // reset; re-notify on next crossing
            } else {
                (QuotaStep::Nothing, state) // between 90% and cap: hold
            }
        }
    }
}

/// Kernel-authoritative per-user disk usage in KiB for the enforce loop. Uses
/// `quota -u -w` (whole-user accounting, the same scope `setquota -u` caps) and
/// returns `None` when the quota subsystem isn't active/readable — so the loop
/// SKIPS the site rather than acting on an unreliable number. We deliberately do
/// NOT gate on exit status: `quota` exits 1 precisely when the user is OVER
/// quota (the case we care about) and only 2 on a real error; we instead key on
/// whether a numeric data line was produced. (The `du` fallback used by the
/// read-only report measures only the docroot, a different scope — never used
/// to drive a suspend/resume decision.)
async fn quota_used_kib(user: &str) -> Option<i64> {
    let out = tokio::process::Command::new("/usr/bin/quota")
        .args(["-u", "-w", user])
        .output()
        .await
        .ok()?;
    let s = String::from_utf8_lossy(&out.stdout);
    for line in s.lines() {
        let cols: Vec<&str> = line.split_whitespace().collect();
        // Data line: "<device> <blocks> <quota> <limit> ...". blocks = cols[1],
        // possibly with a trailing '*' (over soft limit). Header lines have a
        // non-numeric cols[1] and are skipped.
        if cols.len() >= 2 {
            if let Ok(u) = cols[1].trim_end_matches('*').parse::<i64>() {
                return Some(u);
            }
        }
    }
    None
}

/// Returns (current_disk_kib, quotas_enabled_on_fs, setup_hint).
async fn quota_probe_current(user: &str, home_dir: &str) -> (i64, bool, String) {
    // Whether the quota SUBSYSTEM is active on the fs holding home_dir, via the
    // SAME probe the enable flow uses (`quotaon -p`). We must NOT infer this
    // from per-user `quota` output: `quota -q` prints nothing while the user is
    // UNDER quota, which is the normal case right after enabling (no cap set
    // yet) — so the old heuristic read "enabled" as false and the banner never
    // cleared even though quotas were on.
    let enabled = match mount_point_for(home_dir).await {
        Some(mp) => ext_quota_on(&mp).await,
        None => false,
    };

    // Current usage: prefer the kernel's accounting (`quota -u -w`, no `-q` so
    // it prints even when under quota), else `du`.
    let mut used = 0i64;
    if let Ok(out) = tokio::process::Command::new("/usr/bin/quota")
        .args(["-u", "-w", user])
        .output()
        .await
    {
        if out.status.success() {
            let s = String::from_utf8_lossy(&out.stdout);
            for line in s.lines() {
                let cols: Vec<&str> = line.split_whitespace().collect();
                if cols.len() >= 2 {
                    if let Ok(u) = cols[1].trim_end_matches('*').parse::<i64>() {
                        used = u;
                        break;
                    }
                }
            }
        }
    }
    // NO `du` FALLBACK HERE. It used to run whenever the kernel probe
    // returned 0 — which is every box without kernel quotas, i.e. the default
    // — walking the site's entire tree, with no timeout, on every hosting
    // detail page load. On a 20 GB site with a cold page cache that is
    // seconds to tens of seconds of wall clock before anything renders, for a
    // number that is only ENFORCED when quotas are on.
    //
    // The caller substitutes the last sampled figure instead (see quota_get):
    // five minutes stale and instant beats exact and unusable. `du` still
    // runs, but on the sampler's schedule, where taking a while is fine.

    let hint = if enabled {
        String::new()
    } else {
        "Kernel quotas aren't enabled on this filesystem. Disk usage is shown from `du`, but `setquota` won't enforce caps. Use the \"Enable kernel quotas\" button to set this up automatically.".to_string()
    };
    (used, enabled, hint)
}

/// Run a command, returning trimmed stdout (+ stderr) for status messages.
/// Run a quota-related command. Returns `(success, text)` where `success`
/// reflects the process **exit status** (not whether it printed anything) and
/// `text` is the merged stdout+stderr for diagnostics/messages. Callers that
/// need to know "did it work?" must look at `success` — parsing English out of
/// `text` is fragile (a command can exit 0 yet print an advisory to stderr,
/// e.g. systemd's "fstab modified, run daemon-reload" hint after a remount).
async fn quota_run_cmd(bin: &str, args: &[&str]) -> (bool, String) {
    match tokio::process::Command::new(bin).args(args).output().await {
        Ok(o) => {
            let mut s = String::from_utf8_lossy(&o.stdout).trim().to_string();
            let e = String::from_utf8_lossy(&o.stderr);
            if !e.trim().is_empty() {
                if !s.is_empty() {
                    s.push_str("; ");
                }
                s.push_str(e.trim());
            }
            if s.is_empty() {
                s = format!("exit {}", o.status.code().unwrap_or(-1));
            }
            (o.status.success(), s)
        }
        Err(e) => (false, format!("spawn {bin}: {e}")),
    }
}

/// Like `quota_run_cmd` but aborts after `secs`, reporting a timeout as a
/// failure. Used for `quotacheck`, which scans every inode on the filesystem
/// and can run for minutes on a large/busy disk — since enabling quotas now
/// happens inline on a quota save, an unbounded quotacheck could otherwise hang
/// the RPC. The spawned process is left to finish in the background (it's
/// building the aquota files either way); we just stop waiting on it.
async fn quota_run_cmd_timeout(bin: &str, args: &[&str], secs: u64) -> (bool, String) {
    match tokio::time::timeout(
        std::time::Duration::from_secs(secs),
        quota_run_cmd(bin, args),
    )
    .await
    {
        Ok(r) => r,
        Err(_) => (
            false,
            format!("{bin} still running after {secs}s — left to finish in the background"),
        ),
    }
}

/// `/proc/self/mounts` escapes spaces (and a few others) octally.
fn unescape_mount_field(s: &str) -> String {
    s.replace("\\040", " ")
        .replace("\\011", "\t")
        .replace("\\134", "\\")
}

/// Byte ranges (start, end) of each whitespace-delimited field in an fstab
/// line. fstab separates fields with spaces and/or tabs only, so we split on
/// exactly those — preserving the original separators between fields lets a
/// caller splice one field without disturbing the rest of the line (comments,
/// alignment, an inline `# ...` tail).
fn fstab_field_ranges(line: &str) -> Vec<(usize, usize)> {
    let bytes = line.as_bytes();
    let mut ranges = Vec::new();
    let mut i = 0;
    while i < bytes.len() {
        while i < bytes.len() && (bytes[i] == b' ' || bytes[i] == b'\t') {
            i += 1;
        }
        if i >= bytes.len() {
            break;
        }
        let start = i;
        while i < bytes.len() && bytes[i] != b' ' && bytes[i] != b'\t' {
            i += 1;
        }
        ranges.push((start, i));
    }
    ranges
}

/// Pure core of the fstab edit: given the file `content`, return the rewritten
/// content with `to_add` options appended to the options column of the line for
/// `mount_point`. `Ok(Some(new))` = a change is needed, `Ok(None)` = the
/// options were already present (no write), `Err` = no matching mount line.
///
/// Only the options column (field 4) of the one matching line is touched —
/// every other byte (leading whitespace, separators, an inline `# ...` tail,
/// blank/comment lines, the trailing-newline style) is preserved verbatim so
/// the rewrite is a minimal, safe diff that can never break boot.
fn fstab_with_quota_options(
    content: &str,
    mount_point: &str,
    to_add: &[&str],
) -> Result<Option<String>, String> {
    let mut found = false;
    let mut added_any = false;
    let mut out: Vec<String> = Vec::new();
    let had_trailing_nl = content.ends_with('\n');
    for line in content.lines() {
        let t = line.trim_start();
        if t.is_empty() || t.starts_with('#') {
            out.push(line.to_string());
            continue;
        }
        let ranges = fstab_field_ranges(line);
        // Field 1 = mountpoint, field 3 = options. Both fstab and
        // /proc/self/mounts octal-escape spaces/tabs/backslashes, so compare
        // after unescaping — otherwise a mountpoint with a space (escaped in
        // fstab, literal in our `mount_point`) would never match.
        let is_match = ranges.len() >= 4
            && unescape_mount_field(&line[ranges[1].0..ranges[1].1]) == mount_point;
        if is_match {
            found = true;
            let (opt_start, opt_end) = ranges[3];
            let mut opts: Vec<String> = line[opt_start..opt_end]
                .split(',')
                .filter(|s| !s.is_empty())
                .map(|s| s.to_string())
                .collect();
            for o in to_add {
                if !opts.iter().any(|x| x == o) {
                    opts.push((*o).to_string());
                    added_any = true;
                }
            }
            // Splice ONLY the options column; everything else stays byte-for-byte.
            let spliced = format!(
                "{}{}{}",
                &line[..opt_start],
                opts.join(","),
                &line[opt_end..]
            );
            out.push(spliced);
        } else {
            out.push(line.to_string());
        }
    }
    if !found {
        return Err(format!("no /etc/fstab entry for {mount_point}"));
    }
    if !added_any {
        return Ok(None);
    }
    let mut new_content = out.join("\n");
    if had_trailing_nl {
        new_content.push('\n');
    }
    Ok(Some(new_content))
}

/// Ensure `/etc/fstab` carries the quota mount option(s) on the line for
/// `mount_point`. Returns Ok(true) if a change was written, Ok(false) if
/// the option was already present, Err if there's no matching fstab line.
/// Writes atomically (tmp + rename) and only ever appends to field 4 of
/// the one matching line — never restructures the file.
async fn ensure_fstab_quota_option(mount_point: &str, is_xfs: bool) -> Result<bool, String> {
    let path = "/etc/fstab";
    let content = tokio::fs::read_to_string(path)
        .await
        .map_err(|e| format!("read {path}: {e}"))?;
    let to_add: &[&str] = if is_xfs {
        // XFS user+group quota in its native spelling. This MUST match the
        // enforce path, which uses `setquota -u` (user quotas): `prjquota`
        // would provision PROJECT accounting that `setquota -u` can't target,
        // so a cap would silently never apply even after a reboot.
        &["uquota", "gquota"]
    } else {
        &["usrquota", "grpquota"]
    };
    let new_content = match fstab_with_quota_options(&content, mount_point, to_add)? {
        Some(c) => c,
        None => return Ok(false),
    };
    let tmp = format!("{path}.hyperion.tmp");
    tokio::fs::write(&tmp, new_content.as_bytes())
        .await
        .map_err(|e| format!("write {tmp}: {e}"))?;
    // Carry the original fstab's permission bits onto the replacement so a
    // hardened mode (e.g. 0600) survives the atomic swap instead of being
    // reset to the umask default. Owner stays root:root — the agent is root.
    if let Ok(meta) = tokio::fs::metadata(path).await {
        let _ = tokio::fs::set_permissions(&tmp, meta.permissions()).await;
    }
    tokio::fs::rename(&tmp, path)
        .await
        .map_err(|e| format!("rename {tmp}: {e}"))?;
    Ok(true)
}

/// True when ext-family quotas report active on `mount_point`.
///
/// `quotaon -p` always exits 0 (it's a query), so we have to read its text.
/// Modern quota-tools print one line per type, e.g.
///   `user quota on /home (/dev/sda3) is on`
///   `group quota on /home (/dev/sda3) is off`
/// older builds print `... user quotas turned on`. We treat the fs as enabled
/// when any line ends in the "on" state (`is on` / `turned on`); crucially
/// `is on` is NOT a substring of `is off`, so an off line never false-matches.
async fn ext_quota_on(mount_point: &str) -> bool {
    let (_ok, out) = quota_run_cmd("/usr/sbin/quotaon", &["-p", mount_point]).await;
    quota_report_shows_on(&out)
}

/// Parse `quotaon -p` output and report whether any quota type is active.
/// `is on` / `turned on` mean active; `is off` does NOT contain `is on`, so
/// an off-only report correctly reads as inactive.
fn quota_report_shows_on(out: &str) -> bool {
    out.lines().any(|l| {
        let l = l.to_lowercase();
        l.contains("is on") || l.contains("turned on")
    })
}

/// Enable Linux kernel disk quotas on the filesystem carrying `home_path`.
/// Steps assume root (the agent runs as root); a non-root run surfaces as
/// a clear message, not a panic. ext-family filesystems get the full
/// remount + quotacheck + quotaon; XFS quotas only come up at mount time,
/// so there we update fstab and ask for a reboot.
/// Minimal view of agent.toml's `[email]` section, read fresh from disk.
#[derive(Default)]
/// The two `[email]` keys that shape DIRECT-MX delivery rather than the
/// relay. Split out so `mta_reconfigure` can read them off the on-disk
/// section before that section is consumed building the relay config.
struct DirectMxTuning {
    inet_protocols: String,
    bind_address: String,
}

#[derive(Default)]
struct EmailTomlView {
    enabled: bool,
    smtp_host: String,
    smtp_port: i64,
    smtp_user: String,
    smtp_password: String,
    from_address: String,
    from_name: String,
    security: String,
    default_to: String,
    inet_protocols: String,
    bind_address: String,
}

/// Read the `[email]` section straight from agent.toml so callers see the
/// CURRENT on-disk config — not the value loaded into the process at startup.
/// Lets `mta_reconfigure` apply a just-saved config without an agent restart,
/// and lets `mta_diagnostics` pre-fill the Settings → Mail form per node.
fn load_email_section(path: &std::path::Path) -> EmailTomlView {
    let doc = match crate::config_persist::load(path) {
        Ok(d) => d,
        Err(_) => return EmailTomlView::default(),
    };
    let t = doc.as_table().get("email");
    let s = |k: &str| {
        t.and_then(|x| x.get(k))
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .to_string()
    };
    EmailTomlView {
        enabled: t
            .and_then(|x| x.get("enabled"))
            .and_then(|v| v.as_bool())
            .unwrap_or(false),
        smtp_host: s("smtp_host"),
        smtp_port: t
            .and_then(|x| x.get("smtp_port"))
            .and_then(|v| v.as_integer())
            .unwrap_or(0),
        smtp_user: s("smtp_user"),
        smtp_password: s("smtp_password"),
        from_address: s("from_address"),
        from_name: s("from_name"),
        security: s("security"),
        default_to: s("default_to"),
        inet_protocols: s("inet_protocols"),
        bind_address: s("bind_address"),
    }
}

/// Ensure the `quota` user-space tools are installed (quotaon / quotacheck /
/// setquota ship in Debian's `quota` package, absent from a base install).
/// Installs on demand via apt — assumes root (the caller already checked).
/// Returns a clear, actionable message on failure instead of letting the
/// downstream commands fail with a bare "No such file or directory".
/// Available bytes on the filesystem that holds `path`, via `df -P -B1`.
/// `None` on any exec/parse failure — the caller treats unknown as "don't
/// block the backup".
async fn fs_avail_bytes(path: &std::path::Path) -> Option<u64> {
    let out = tokio::process::Command::new("/usr/bin/df")
        .args(["-P", "-B1", "--", &path.display().to_string()])
        .output()
        .await
        .ok()?;
    if !out.status.success() {
        return None;
    }
    // `df -P` output: a header line, then one data line whose 4th column is
    // "Available" (in 1-byte blocks because of -B1).
    let text = String::from_utf8_lossy(&out.stdout);
    let line = text.lines().nth(1)?;
    line.split_whitespace().nth(3)?.parse::<u64>().ok()
}

/// Apparent size in bytes of the tree at `path`, via `du -sb`. Capped by a
/// 60 s timeout so a huge/slow tree can't stall a backup; `None` on
/// failure/timeout (caller treats unknown as "don't block").
async fn dir_size_bytes(path: &std::path::Path) -> Option<u64> {
    let fut = tokio::process::Command::new("/usr/bin/du")
        .args(["-sb", "--", &path.display().to_string()])
        .output();
    let out = tokio::time::timeout(std::time::Duration::from_secs(60), fut)
        .await
        .ok()?
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&out.stdout);
    text.split_whitespace().next()?.parse::<u64>().ok()
}

/// `apt-get install quota`. Returns (succeeded, combined stdout+stderr) — apt
/// prints the REAL dpkg error (e.g. "Read-only file system") to STDOUT, while
/// only the generic "E: Sub-process ... error code (1)" goes to stderr, so we
/// must capture both to diagnose a failure.
async fn apt_install_quota() -> (bool, String) {
    match tokio::process::Command::new("/usr/bin/apt-get")
        .args(["install", "-y", "--no-install-recommends", "quota"])
        .env("DEBIAN_FRONTEND", "noninteractive")
        .output()
        .await
    {
        Ok(o) => {
            let mut s = String::from_utf8_lossy(&o.stdout).into_owned();
            s.push_str(&String::from_utf8_lossy(&o.stderr));
            (o.status.success(), s)
        }
        Err(e) => (false, format!("couldn't exec apt-get: {e}")),
    }
}

/// Operator-facing failure message carrying the last few lines of apt's output
/// (the real cause) instead of the opaque "Sub-process dpkg returned 1".
fn quota_install_err(output: &str) -> String {
    let tail = output
        .lines()
        .filter(|l| !l.trim().is_empty())
        .rev()
        .take(6)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .collect::<Vec<_>>()
        .join(" | ");
    format!(
        "the `quota` package isn't installed and auto-install failed: {tail} — \
         on the node, run `sudo dpkg --configure -a` then `sudo apt-get install -y quota` \
         (if `/` is read-only, first `sudo mount -o remount,rw /`)."
    )
}

async fn ensure_quota_tools() -> Result<(), String> {
    let have = |p: &str| std::path::Path::new(p).exists();
    if have("/usr/sbin/quotaon") && have("/usr/sbin/quotacheck") {
        return Ok(());
    }
    tracing::info!("quota tools missing — installing the `quota` package via apt-get");

    let (ok, combined) = apt_install_quota().await;
    if ok && have("/usr/sbin/quotaon") {
        return Ok(());
    }

    // The two usual reasons `dpkg returned error code (1)` here are (a) this
    // node's read-only-/usr hardening (apt can't write) and (b) a half-
    // configured dpkg from an interrupted run. Address whichever applies, then
    // retry once. The remount mirrors the operator-facing ROFS unlock
    // (remount_usr_rw); the hardening re-applies on the next reboot.
    let lower = combined.to_lowercase();
    let mut recovered = false;
    if lower.contains("read-only file system") || lower.contains("erofs") {
        tracing::warn!("apt failed on a read-only filesystem — remounting rw and retrying");
        let _ = tokio::process::Command::new("/usr/bin/mount")
            .args(["-o", "remount,rw", "/"])
            .output()
            .await;
        let _ = tokio::process::Command::new("/usr/bin/mount")
            .args(["-o", "remount,rw", "/usr"])
            .output()
            .await;
        recovered = true;
    }
    if lower.contains("dpkg was interrupted")
        || lower.contains("--configure -a")
        || lower.contains("half-configured")
        || lower.contains("half-installed")
    {
        tracing::warn!("dpkg is wedged — running `dpkg --configure -a` before retry");
        let _ = tokio::process::Command::new("/usr/bin/dpkg")
            .args(["--configure", "-a"])
            .env("DEBIAN_FRONTEND", "noninteractive")
            .output()
            .await;
        recovered = true;
    }

    if recovered {
        let (ok2, combined2) = apt_install_quota().await;
        if ok2 && have("/usr/sbin/quotaon") {
            return Ok(());
        }
        return Err(quota_install_err(&combined2));
    }
    Err(quota_install_err(&combined))
}

async fn enable_kernel_quotas(home_path: &str) -> hyperion_types::QuotaEnableSummary {
    use hyperion_types::QuotaEnableSummary as Summary;
    let fail = |message: String, mount_point: String, fs_type: String| Summary {
        ok: false,
        requires_reboot: false,
        fs_type,
        mount_point,
        message,
    };

    // 0. Root check — mount / quotacheck / quotaon all need it.
    let uid = tokio::process::Command::new("/usr/bin/id")
        .arg("-u")
        .output()
        .await
        .ok()
        .and_then(|o| {
            String::from_utf8_lossy(&o.stdout)
                .trim()
                .parse::<u32>()
                .ok()
        });
    if uid != Some(0) {
        return fail(
            "the agent isn't running as root, so it can't change mount options or enable quotas"
                .into(),
            String::new(),
            String::new(),
        );
    }

    // 0b. The quota user-space tools (quotaon / quotacheck / setquota) live in
    // the Debian `quota` package, which isn't part of a base install — without
    // it the steps below fail with "No such file or directory" (and a reboot
    // never fixes it). This feature is meant to be automatic, so install the
    // package on demand before we touch fstab.
    if let Err(e) = ensure_quota_tools().await {
        return fail(e, String::new(), String::new());
    }

    // 1. Discover the mount carrying home_path (longest matching mountpoint).
    let mounts = match tokio::fs::read_to_string("/proc/self/mounts").await {
        Ok(s) => s,
        Err(e) => {
            return fail(
                format!("couldn't read /proc/self/mounts: {e}"),
                String::new(),
                String::new(),
            )
        }
    };
    let mut best: Option<(String, String, String, String)> = None; // (mount, fstype, options, device)
    for line in mounts.lines() {
        let f: Vec<&str> = line.split_whitespace().collect();
        if f.len() < 4 {
            continue;
        }
        let mp = unescape_mount_field(f[1]);
        let covers = home_path == mp
            || mp == "/"
            || home_path.starts_with(&format!("{}/", mp.trim_end_matches('/')));
        if covers {
            let better = best
                .as_ref()
                .map(|(m, _, _, _)| mp.len() > m.len())
                .unwrap_or(true);
            if better {
                best = Some((
                    mp,
                    f[2].to_string(),
                    f[3].to_string(),
                    unescape_mount_field(f[0]),
                ));
            }
        }
    }
    let (mount_point, fs_type, cur_opts, device) = match best {
        Some(v) => v,
        None => {
            return fail(
                format!("couldn't find the mount for {home_path}"),
                String::new(),
                String::new(),
            )
        }
    };

    let is_xfs = fs_type == "xfs";
    let already_mounted = cur_opts.split(',').any(|o| {
        // ext family: usrquota/grpquota/prjquota · XFS: uquota/gquota/pquota
        // (and the bare `quota` alias). Any of these means the quota option is
        // already live on this mount.
        matches!(
            o,
            "usrquota" | "grpquota" | "prjquota" | "quota" | "uquota" | "gquota" | "pquota"
        )
    });

    // 2. Make sure /etc/fstab carries the quota option for next boot.
    let fstab_added = match ensure_fstab_quota_option(&mount_point, is_xfs).await {
        Ok(added) => added,
        Err(e) => {
            return fail(
                format!("couldn't update /etc/fstab: {e}"),
                mount_point,
                fs_type,
            )
        }
    };
    let fstab_note = if fstab_added {
        "/etc/fstab updated"
    } else {
        "/etc/fstab already had it"
    };

    // 3. XFS: quota accounting only initialises at mount, never on a live fs.
    if is_xfs {
        // If the option is already live AND reports on, accounting is active
        // now (XFS turns it on at mount) — nothing to reboot for.
        if already_mounted && ext_quota_on(&mount_point).await {
            return Summary {
                ok: true,
                requires_reboot: false,
                fs_type,
                mount_point,
                message: "XFS kernel quotas are already active on this filesystem — set a disk limit below to enforce a per-hosting cap."
                    .into(),
            };
        }
        return Summary {
            ok: false,
            requires_reboot: true,
            fs_type,
            mount_point: mount_point.clone(),
            message: format!(
                "{fstab_note}. XFS quotas can only initialise at mount time — reboot the node (or remount {mount_point} while it's idle) to activate them."
            ),
        };
    }

    // 3b. Already active? Then there's nothing to do — and running the
    // remount/quotacheck/quotaon dance below would only emit confusing errors:
    // on a filesystem using the ext4 *quota feature* (internal/journaled
    // quotas), quotacheck refuses ("quota for users is enabled … might damage")
    // and `quotaon` fails EBUSY ("Device or resource busy") precisely because
    // quotas are ALREADY on. Detect that up front via the canonical probe and
    // report success cleanly. setquota -u works against this state.
    if ext_quota_on(&mount_point).await {
        return Summary {
            ok: true,
            requires_reboot: false,
            fs_type,
            mount_point,
            message: "Kernel quotas are already active on this filesystem — set a disk limit below to enforce a per-hosting cap.".into(),
        };
    }

    // 4. ext-family: remount to load the quota option, then build + turn on.
    if !already_mounted {
        let (remount_ok, remount_msg) = quota_run_cmd(
            "/usr/bin/mount",
            &["-o", "remount,usrquota,grpquota", &mount_point],
        )
        .await;
        // Success is the process EXIT STATUS, not the text: a clean remount can
        // still print an advisory to stderr (e.g. systemd's "fstab modified,
        // run daemon-reload" hint after we edited fstab above). Only a non-zero
        // exit is a real failure.
        if !remount_ok {
            let lower = remount_msg.to_lowercase();
            let busy = lower.contains("busy") || lower.contains("in use");
            if busy {
                // Filesystem is live and held open — only a reboot (or freeing
                // it) can remount it. fstab is already set, so the reboot sticks.
                return Summary {
                    ok: false,
                    requires_reboot: true,
                    fs_type,
                    mount_point: mount_point.clone(),
                    message: format!(
                        "{fstab_note}, but {mount_point} is busy and couldn't be remounted live ({remount_msg}). Reboot the node (or free the filesystem and retry) to activate quotas."
                    ),
                };
            }
            // A hard error (bad option, read-only fs, unsupported option, …).
            // Surface the actual error instead of silently proceeding to
            // quotacheck/quotaon on an fs that never got the quota option.
            // A reboot only helps when the SAME fstab option would mount
            // cleanly next time (e.g. a transient read-only `/`). A bad /
            // unsupported option fails identically at boot, so don't promise a
            // reboot for those — they need operator attention.
            let bad_option = lower.contains("bad option")
                || lower.contains("unsupported")
                || lower.contains("unrecognized")
                || lower.contains("invalid argument");
            return Summary {
                ok: false,
                requires_reboot: mount_point == "/" && !bad_option,
                fs_type,
                mount_point: mount_point.clone(),
                message: if bad_option {
                    format!(
                        "{fstab_note}, but {mount_point} rejected the quota mount option: {remount_msg}. This filesystem/kernel doesn't support it the way we tried — a reboot won't change that; it needs operator attention."
                    )
                } else {
                    format!(
                        "{fstab_note}, but remounting {mount_point} with quota options failed: {remount_msg}."
                    )
                },
            };
        }
    }
    // quotacheck builds aquota.user/.group; -m allows it while mounted. Bound
    // it so a huge/busy filesystem can't hang the save RPC (it keeps building
    // in the background; quotaon below still tries, and a re-save finishes it).
    let (_check_ok, check_msg) =
        quota_run_cmd_timeout("/usr/sbin/quotacheck", &["-ugm", &mount_point], 240).await;
    let (_qon_ok, qon) = quota_run_cmd("/usr/sbin/quotaon", &["-v", &mount_point]).await;
    if ext_quota_on(&mount_point).await {
        Summary {
            ok: true,
            requires_reboot: false,
            fs_type,
            mount_point,
            message: "Kernel quotas are now active — set a disk limit below to enforce a per-hosting cap.".into(),
        }
    } else if ext4_has_quota_feature(&device).await == Some(false) {
        // Accounting didn't start AND the on-disk `quota` feature is absent: a
        // reboot just re-reads the same fstab option and still won't enable it.
        // The one-time fix is `tune2fs -O quota`, not a reboot.
        Summary {
            ok: false,
            requires_reboot: false,
            fs_type,
            mount_point: mount_point.clone(),
            message: format!(
                "{fstab_note} + quotacheck/quotaon ran, but {mount_point} ({device}) lacks the on-disk quota feature, so accounting can't start — a reboot won't help. Enable it once with `tune2fs -O quota {device}` ({mount_point} must be unmounted, or use single-user mode for `/`), then re-run. (quotacheck: {check_msg}; quotaon: {qon})"
            ),
        }
    } else {
        Summary {
            ok: false,
            requires_reboot: true,
            fs_type,
            mount_point: mount_point.clone(),
            message: format!(
                "{fstab_note} + quotacheck/quotaon ran, but quotas don't report active yet (quotacheck: {check_msg}; quotaon: {qon}). A reboot usually finishes the setup."
            ),
        }
    }
}

/// Whether the ext-family filesystem on `device` carries the on-disk `quota`
/// feature flag (`tune2fs -l`). Returns `None` when we can't tell — tune2fs
/// missing, a non-ext device, or an unparseable report — so callers never
/// over-claim "feature absent" and wrongly suppress the reboot advice. When
/// this is `Some(false)`, the mount option alone can't start accounting; the
/// fs needs `tune2fs -O quota` first (a reboot won't help).
async fn ext4_has_quota_feature(device: &str) -> Option<bool> {
    let out = tokio::process::Command::new("/usr/sbin/tune2fs")
        .args(["-l", device])
        .output()
        .await
        .ok()?;
    if !out.status.success() {
        return None;
    }
    let text = String::from_utf8_lossy(&out.stdout);
    for line in text.lines() {
        if let Some((key, val)) = line.split_once(':') {
            if key.trim().eq_ignore_ascii_case("Filesystem features") {
                return Some(val.split_whitespace().any(|f| f == "quota"));
            }
        }
    }
    None
}

/// Snapshot of one filesystem's usage, parsed from `df -P -B1`.
/// `used_pct` is rounded down so a 79.999% filesystem is reported
/// as 79, not 80 — operators trust round trips of this number.
#[derive(Debug, Clone)]
struct DiskUsage {
    mount: String,
    total_bytes: i64,
    used_bytes: i64,
    used_pct: i64,
}

/// Probe filesystem usage via `df -P -B1` on the mounts the panel
/// cares about. POSIX mode (`-P`) keeps the columns stable across
/// distros; `-B1` outputs bytes (not KiB) so the math is exact.
///
/// Returns empty on any parsing failure — alerts are best-effort
/// and we'd rather under-warn than crash the dashboard.
async fn probe_disk_usages() -> std::io::Result<Vec<DiskUsage>> {
    // Hand-picked list: the mountpoints any practical Hyperion
    // node could fill up. `/var` is where hosting trees + DB dumps
    // + nginx logs + apt cache + hyperion's own data dir
    // (/var/lib/hyperion) all live; `/` covers everything else
    // including immutable images that don't carve /var separately.
    // df ignores a missing mount with exit 1 and an error on
    // stderr; we just drop those rows.
    let out = tokio::process::Command::new("df")
        .args(["-P", "-B1", "/", "/var", "/home", "/tmp"])
        .output()
        .await?;
    let stdout = String::from_utf8_lossy(&out.stdout);
    let mut seen_mounts = std::collections::HashSet::new();
    let mut rows = Vec::new();
    // First line is the header — skip it.
    for line in stdout.lines().skip(1) {
        // `df -P -B1` columns: Filesystem 1-blocks Used Available Capacity Mounted-on
        let cols: Vec<&str> = line.split_whitespace().collect();
        if cols.len() < 6 {
            continue;
        }
        let mount = cols[cols.len() - 1].to_string();
        // The same physical device often appears multiple times in
        // our requested list (`/` and `/home` on a single-partition
        // VPS). Dedup by mount so we don't double-alert.
        if !seen_mounts.insert(mount.clone()) {
            continue;
        }
        let total: i64 = cols[1].parse().unwrap_or(0);
        let used: i64 = cols[2].parse().unwrap_or(0);
        if total <= 0 {
            continue;
        }
        // `df` rounds Capacity to whole percent; redo it ourselves
        // from bytes for accuracy.
        let pct = (used.saturating_mul(100) / total).clamp(0, 100);
        rows.push(DiskUsage {
            mount,
            total_bytes: total,
            used_bytes: used,
            used_pct: pct,
        });
    }
    Ok(rows)
}

/// Format `bytes` as a short human string ("12.3 GiB"). Used by
/// the dashboard banner — the operator wants "8 GiB free" not
/// "8589934592 bytes". Caps at TiB; anything bigger would be a
/// genuine surprise on a hosting node.
fn human_bytes(bytes: i64) -> String {
    let units = [
        ("TiB", 1i64 << 40),
        ("GiB", 1 << 30),
        ("MiB", 1 << 20),
        ("KiB", 1 << 10),
    ];
    for (label, scale) in units.iter() {
        if bytes >= *scale {
            return format!("{:.1} {}", bytes as f64 / *scale as f64, label);
        }
    }
    format!("{bytes} B")
}

/// Write a sensitive blob to disk with restrictive permissions
/// (0600, root-owned via the agent's pre-existing root mode).
/// Creates the parent dir if needed. Used by the backup-target
/// secret storage so the access key never ends up in audit logs
/// or shell history.
async fn write_secret_file(path: &str, content: &[u8]) -> std::io::Result<()> {
    use std::os::unix::fs::PermissionsExt;
    let pb = std::path::PathBuf::from(path);
    if let Some(parent) = pb.parent() {
        tokio::fs::create_dir_all(parent).await?;
        let mut perms = tokio::fs::metadata(parent).await?.permissions();
        perms.set_mode(0o700);
        let _ = tokio::fs::set_permissions(parent, perms).await;
    }
    tokio::fs::write(&pb, content).await?;
    let mut perms = tokio::fs::metadata(&pb).await?.permissions();
    perms.set_mode(0o600);
    tokio::fs::set_permissions(&pb, perms).await?;
    Ok(())
}

