    #[tokio::test]
    async fn set_expiry_schedules_actions_and_clear_cancels() {
        let pool = open_memory().await.expect("open");
        let s = svc(pool.clone(), happy_mocks());
        s.create(req("ex.cz")).await.expect("create");
        let sel = HostingSelector::Domain(Domain::parse("ex.cz").unwrap());
        let exp = now_secs() + 2 * 86_400;
        let mut e = hyperion_types::HostingExpiry::defaults();
        e.expires_at = Some(exp);
        e.grace_days = 7;
        e.owner_email = Some("k@x.cz".into());
        let stored = s.set_expiry(sel.clone(), e).await.expect("set");
        assert_eq!(stored.expires_at, Some(exp));
        assert_eq!(stored.grace_days, 7);

        let due_far_future = hyperion_state::scheduler::pending_due(&pool, exp + 100 * 86_400, 100)
            .await
            .expect("pending");
        let actions: Vec<&str> = due_far_future.iter().map(|a| a.action.as_str()).collect();
        assert!(actions.contains(&"suspend_expired"));
        assert!(actions.contains(&"delete_expired"));
        assert!(actions.contains(&"notify_1d"));

        s.clear_expiry(sel).await.expect("clear");
        let after = hyperion_state::scheduler::pending_due(&pool, exp + 100 * 86_400, 100)
            .await
            .expect("pending");
        assert!(after.is_empty(), "actions canceled");
    }

    /// The whole point of widening the session probe: a privilege taken away
    /// must be gone on the NEXT request, not when the cookie happens to
    /// expire. Before this, `web_session_touch` returned a bare bool and the
    /// role and capabilities came from the cookie, so an admin demoted at
    /// 09:00 kept full access until as late as 17:00.
    #[tokio::test]
    async fn a_demotion_takes_effect_on_the_next_request() {
        let pool = open_memory().await.expect("open");
        let s = svc(pool.clone(), happy_mocks());
        let uid = s
            .web_user_create(
                "vera".into(),
                "vera@example.cz".into(),
                "correct horse battery".into(),
                "admin".into(),
            )
            .await
            .expect("create user");

        let before = s
            .web_session_touch("sid-not-in-the-ledger", uid)
            .await
            .expect("touch");
        assert!(before.known_user && !before.locked);
        assert_eq!(before.role, "admin");

        s.web_user_set_role(uid, "viewer".into())
            .await
            .expect("demote");

        let after = s
            .web_session_touch("sid-not-in-the-ledger", uid)
            .await
            .expect("touch");
        assert_eq!(after.role, "viewer", "the demotion did not take effect");
        assert!(
            after.caps != before.caps,
            "a viewer must not keep an admin's capabilities"
        );
    }

    /// Locking is how an admin stops someone NOW. It used to stop only their
    /// next login, which is not what the button says.
    #[tokio::test]
    async fn locking_an_account_ends_its_live_session() {
        let pool = open_memory().await.expect("open");
        let s = svc(pool.clone(), happy_mocks());
        let uid = s
            .web_user_create(
                "lada".into(),
                "lada@example.cz".into(),
                "correct horse battery".into(),
                "operator".into(),
            )
            .await
            .expect("create user");
        assert!(!s.web_session_touch("sid", uid).await.expect("touch").locked);

        s.web_user_set_locked(uid, true, Some("offboarded".into()))
            .await
            .expect("lock");
        assert!(s.web_session_touch("sid", uid).await.expect("touch").locked);
    }

    /// A deleted account must not keep acting through a cookie that is still
    /// validly signed.
    #[tokio::test]
    async fn a_deleted_user_has_no_standing() {
        let pool = open_memory().await.expect("open");
        let s = svc(pool.clone(), happy_mocks());
        let st = s.web_session_touch("sid", 999_999).await.expect("touch");
        assert!(!st.known_user, "an unknown user id must not be known");
        assert_eq!(st.caps, 0, "and carries no capabilities of its own");
        // NOT reported as locked: there is no row to say so. The web layer
        // distinguishes a deleted account from the bootstrap admin, whose
        // record lives in a file rather than in this table.
        assert!(!st.locked);
    }

    #[tokio::test]
    async fn scheduler_tick_runs_suspend_for_expired_hosting() {
        let pool = open_memory().await.expect("open");
        let s = svc(pool.clone(), suspend_mocks());
        s.create(req("ex.cz")).await.expect("create");
        let sel = HostingSelector::Domain(Domain::parse("ex.cz").unwrap());

        // Written straight to the row, NOT through set_expiry.
        //
        // set_expiry now reads a past date as "renews on this day and month,
        // with us since this year" and rolls it forward, so it can no longer
        // produce an already-expired hosting — that is the whole point of the
        // change. The state under test is still perfectly real: it is what
        // every hosting looks like the day after its expiry passes. So the
        // row is put into that state directly, the way time does it.
        let past = now_secs() - 86_400;
        hyperion_state::scheduler::set_expiry(
            &pool,
            &s.get(sel.clone()).await.expect("get").id,
            Some(past),
            None,
            30,
            "30,7,1",
            None,
            now_secs(),
        )
        .await
        .expect("set expiry row");
        let processed = s.scheduler_tick().await.expect("tick");
        assert!(processed >= 1, "processed: {processed}");

        let detail = s.get(sel).await.expect("get");
        assert_eq!(detail.state, HostingState::Suspended);
    }

